mapper.select:
SELECT g.sku, g.common_name AS commonName, g.spec, g.manufacturer AS manufacturer, g.approval_no AS approvalNo, g.upc, g.brand, c1.name AS categoryL1Name, c2.name AS categoryL2Name, DATE_FORMAT(g.meeting_date, '%Y-%m-%d') AS meetingDate, CASE g.cooperate_result WHEN 'YES' THEN '合作' WHEN 'NO' THEN '不合作' ELSE '待定' END AS cooperateResult, DATE_FORMAT(g.launch_date, '%Y-%m-%d') AS launchDate, CASE WHEN g.current_node_code IS NULL OR g.current_node_code = '' THEN '已完成全流程' ELSE g.current_node_name END AS currentNodeName, (SELECT COUNT(1) FROM qc_goods_material gm2 INNER JOIN qc_material_item mi2 ON mi2.id = gm2.item_id AND mi2.deleted = 0 AND mi2.status = 1 WHERE gm2.goods_id = g.id AND gm2.deleted = 0 AND gm2.status IN ('MISSING','PENDING')) AS gapCount, CASE g.data_source WHEN 'DEMO' THEN '演示' ELSE '录入' END AS dataSource, g.remark FROM qc_ledger_goods g LEFT JOIN qc_category c1 ON c1.id = g.category_l1_id AND c1.deleted = 0 LEFT JOIN qc_category c2 ON c2.id = g.category_l2_id AND c2.deleted = 0
g.deleted = 0
AND (g.sku LIKE CONCAT('%', #{keyword}, '%') OR g.common_name LIKE CONCAT('%', #{keyword}, '%') OR g.brand LIKE CONCAT('%', #{keyword}, '%') OR g.manufacturer LIKE CONCAT('%', #{keyword}, '%'))
AND g.category_l1_id = #{categoryL1Id} AND g.category_l2_id = #{categoryL2Id}
AND g.cooperate_result = #{cooperateResult}
AND g.current_node_code = #{currentNodeCode}
ORDER BY g.updated_at DESC, g.id DESC
